function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[efghinorstuvwxz]+$/.test(s)) return 's uses only the letters e, f, g, h, i, n, o, r, s, t, u, v, w, x, z.';
  const freq = {};
  for (const ch of s) freq[ch] = (freq[ch] || 0) + 1;
  const c = letter => freq[letter] || 0;
  const d = [c('z'), 0, c('w'), 0, c('u'), 0, c('x'), 0, c('g'), 0];
  d[3] = c('h') - d[8]; d[5] = c('f') - d[4]; d[7] = c('s') - d[6];
  d[1] = c('o') - d[0] - d[2] - d[4]; d[9] = c('i') - d[5] - d[6] - d[8];
  if (d.some(x => x < 0)) return 's must be a scrambled list of digit words.';
  const words = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
  const used = {};
  words.forEach((word, digit) => { for (const ch of word) used[ch] = (used[ch] || 0) + d[digit]; });
  if (Object.keys(freq).some(ch => used[ch] !== freq[ch]) || Object.keys(used).some(ch => used[ch] !== c(ch))) return 's must be a scrambled list of digit words.';
  return null;
}

