function originalDigits(s) {
  const freq = {};
  for (const ch of s) {
    freq[ch] = (freq[ch] || 0) + 1;
  }
  const count = letter => freq[letter] || 0;
  const digits = new Array(10).fill(0);
  digits[0] = count('z');
  digits[2] = count('w');
  digits[4] = count('u');
  digits[6] = count('x');
  digits[8] = count('g');
  digits[3] = count('h') - digits[8];
  digits[5] = count('f') - digits[4];
  digits[7] = count('s') - digits[6];
  digits[1] = count('o') - digits[0] - digits[2] - digits[4];
  digits[9] = count('i') - digits[5] - digits[6] - digits[8];
  let result = '';
  for (let digit = 0; digit <= 9; digit++) {
    result += String(digit).repeat(digits[digit]);
  }
  return result;
}

