function originalDigits(s) {
  const words = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
  const left = new Map();
  for (const ch of s) left.set(ch, (left.get(ch) || 0) + 1);
  const canTake = word => [...word].every(ch => (left.get(ch) || 0) >= [...word].filter(c => c === ch).length);
  const counts = new Array(10).fill(0);
  // Peel off whole words, each time choosing a word that is the only one left containing some letter.
  for (const digit of [0, 2, 4, 6, 8, 1, 3, 5, 7, 9]) {
    while (canTake(words[digit])) {
      for (const ch of words[digit]) left.set(ch, left.get(ch) - 1);
      counts[digit]++;
    }
  }
  if ([...left.values()].some(v => v !== 0)) throw new Error('Letters were left over.');
  return counts.map((c, d) => String(d).repeat(c)).join('');
}

